<script lang="ts">import type { Snippet } from 'svelte';let { items = [], label = 'Menu', children }: { items?: { id: string; label: string }[]; label?: string; children?: Snippet } = $props();let open = $state(false);let idx = $state(0);function key(e: KeyboardEvent) { if (e.key === 'ArrowDown') { e.preventDefault(); idx = Math.min((items?.length ?? 1) - 1, idx + 1); } else if (e.key === 'ArrowUp') { e.preventDefault(); idx = Math.max(0, idx - 1); } else if (e.key === 'Escape') open = false; }</script><div class="menu"><button aria-haspopup="menu" aria-expanded={open} onclick={() => (open = !open)}>{label}</button>{#if open}<div role="menu" tabindex="0" onkeydown={key}>{#if children}{@render children()}{/if}{#each items ?? [] as it, i}<div role="menuitem" tabindex="-1" class:active={i === idx}>{it.label}</div>{/each}</div>{/if}</div><style>.menu{position:relative;display:inline-block}.menu [role='menu']{position:absolute;background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--shadow-pop);min-width:160px;z-index:20}.menu [role='menuitem']{padding:var(--space-2) var(--space-4);font-size:var(--fs-sm)}.menu [role='menuitem'].active,.menu [role='menuitem']:hover{background:var(--bg-3)}</style>
